mapper.select:
SELECT /*selectBuyerMpRqQuotaProceStateAdminList*/ Z.BUYER, Z.BUYER_NAME, Z.QUOTATION_NO, Z.QUOTATION_SEQ, Z.REVISION, Z.BTOA_DATE, Z.DESCRIPTION, Z.ATOS_DATE, Z.ATOB_UNIT_PRICE, Z.BTOA_USER_NAME, Z.KEP_USER_ID, Z.SOURCING_STATUS, Z.BTOA_END_DATE, Z.SPECIFICATION, Z.ATOS_END_DATE, Z.STOA_LIST_PRICE, Z.BTOA_USER_DEPT, Z.BTOA_REMARK, Z.BUYER_ITEM_NO, Z.DELAY_STATUS, Z.MAKER_NAME, Z.ORIGIN_NAME, Z.UNIT_MEASURE, Z.ITEM_QTY, Z.AGENT_NAME, Z.IMAGE_KEY, Z.KEP_USER_NAME, Z.REG_ITEM_NO, Z.AGENT, Z.BTOA_USER_ID, Z.BTOA_END_TIME, Z.ATOS_END_TIME, Z.AGENT_REVISION, Z.ATOB_DATE, Z.ATOB_TIME, Z.ATOS_END_FLAG, Z.CMS_USER_NAME, Z.REF_NO, Z.REMARK_URL FROM ( SELECT ROWNUM NUM, Y.BUYER, Y.BUYER_NAME, Y.QUOTATION_NO, Y.QUOTATION_SEQ, Y.REVISION, Y.BTOA_DATE, Y.DESCRIPTION, Y.ATOS_DATE, Y.ATOB_UNIT_PRICE, Y.BTOA_USER_NAME, Y.KEP_USER_ID, Y.SOURCING_STATUS, Y.BTOA_END_DATE, Y.SPECIFICATION, Y.ATOS_END_DATE, Y.STOA_LIST_PRICE, Y.BTOA_USER_DEPT, Y.BTOA_REMARK, Y.BUYER_ITEM_NO, Y.DELAY_STATUS, Y.MAKER_NAME, Y.ORIGIN_NAME, Y.UNIT_MEASURE, Y.ITEM_QTY, Y.AGENT_NAME, Y.IMAGE_KEY, Y.KEP_USER_NAME, Y.REG_ITEM_NO, Y.AGENT, Y.BTOA_USER_ID, Y.BTOA_END_TIME, Y.ATOS_END_TIME, Y.AGENT_REVISION, Y.ATOB_DATE, Y.ATOB_TIME, Y.ATOS_END_FLAG, Y.CMS_USER_NAME, Y.REF_NO, Y.REMARK_URL FROM ( SELECT X.BUYER, X.BUYER_NAME, X.QUOTATION_NO, X.QUOTATION_SEQ, X.REVISION, X.BTOA_DATE, X.DESCRIPTION, X.ATOS_DATE, X.ATOB_UNIT_PRICE, X.BTOA_USER_NAME, X.KEP_USER_ID, X.SOURCING_STATUS, X.BTOA_END_DATE, X.SPECIFICATION, X.ATOS_END_DATE, X.STOA_LIST_PRICE, X.BTOA_USER_DEPT, X.BTOA_REMARK, X.BUYER_ITEM_NO, X.DELAY_STATUS, X.MAKER_NAME, X.ORIGIN_NAME, X.UNIT_MEASURE, X.ITEM_QTY, X.AGENT_NAME, X.IMAGE_KEY, X.KEP_USER_NAME, X.REG_ITEM_NO, X.AGENT, X.BTOA_USER_ID, X.BTOA_END_TIME, X.ATOS_END_TIME, X.AGENT_REVISION, X.ATOB_DATE, X.ATOB_TIME, X.ATOS_END_FLAG, X.CMS_USER_NAME, X.REF_NO, X.REMARK_URL FROM ( SELECT A.BUYER, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE=A.BUYER AND STATUS <> 'D')) AS BUYER_NAME, A.QUOTATION_NO, A.QUOTATION_SEQ, A.REVISION, MAX(A.BTOA_DATE) AS BTOA_DATE, MAX(A.DESCRIPTION) AS DESCRIPTION, MAX(B.ATOS_DATE) AS ATOS_DATE, MAX(A.ATOB_UNIT_PRICE) AS ATOB_UNIT_PRICE, MAX(A.BTOA_USER_NAME) AS BTOA_USER_NAME, MAX(A.KEP_USER_ID) AS KEP_USER_ID, CASE WHEN MAX(A.RECV_FLAG)='GD' THEN '견적취소' ELSE CASE WHEN MAX(A.RECV_FLAG) = 'GS' THEN '결재진행중' ELSE CASE WHEN MAX(A.RECV_FLAG) = 'GR' THEN '결재반려' ELSE CASE WHEN MAX(A.RECV_FLAG)='PM' THEN '내부품의및카탈로그등록중' ELSE CASE WHEN MAX(A.RECV_FLAG)='CC' THEN '장바구니' ELSE CASE WHEN MAX(A.RECV_FLAG)='CM' THEN '합의완료' ELSE CASE WHEN MAX(A.RECV_FLAG)='NW' THEN 'CMS매핑의뢰' ELSE CASE WHEN MAX(A.RECV_FLAG)='CR' THEN 'CMS매핑중' ELSE CASE WHEN MAX(A.RECV_FLAG)='RJ' THEN 'CMS재요청' ELSE CASE WHEN MAX(A.KEP_USER_ID) IS NULL THEN '구매사견적의뢰' ELSE CASE WHEN MAX(B.AGENT_REVISION)=1 AND MAX(A.ATOB_UNIT_PRICE)=0 AND MAX(A.ATOB_SEND_FLAG)='N' AND MAX(B.BID_SUCCESS_FLAG)<>'Y' THEN '공급사견적요청' ELSE CASE WHEN MAX(B.AGENT_REVISION)<>1 AND MAX(A.ATOB_UNIT_PRICE)=0 AND MAX(A.ATOB_SEND_FLAG)='N' THEN '공급사재견적요청' ELSE CASE WHEN MAX(A.ATOB_UNIT_PRICE)=0 AND MAX(A.ATOB_SEND_FLAG)='N' AND MAX(B.BID_SUCCESS_FLAG)='Y' THEN '공급사선정완료' ELSE CASE WHEN MAX(A.BTOA_NEGO_PRICE)=0 AND MAX(A.ATOB_UNIT_PRICE)<>0 AND MAX(A.ATOB_SEND_FLAG)='Y' THEN '구매사견적제시' ELSE CASE WHEN MAX(A.BTOA_NEGO_PRICE)<>0 AND MAX(A.ATOB_UNIT_PRICE)=0 AND MAX(A.ATOB_SEND_FLAG)='Y' THEN '구매사NEGO의뢰' ELSE CASE WHEN MAX(A.BTOA_NEGO_PRICE)<>0 AND MAX(A.ATOB_UNIT_PRICE)<>0 AND MAX(A.ATOB_SEND_FLAG)='Y' THEN '구매사NEGO견적제출' END END END END END END END END END END END END END END END END AS SOURCING_STATUS, MAX(A.BTOA_END_DATE) AS BTOA_END_DATE, MAX(A.SPECIFICATION) AS SPECIFICATION, MAX(B.ATOS_END_DATE) AS ATOS_END_DATE, MAX((SELECT MAX(QTDT.STOA_LIST_PRICE) FROM KEPQTDT QTDT WHERE QTDT.BUYER=A.BUYER AND QTDT.QUOTATION_NO=A.QUOTATION_NO AND QTDT.QUOTATION_SEQ=A.QUOTATION_SEQ AND QTDT.REVISION=A.REVISION AND QTDT.BID_SUCCESS_FLAG='Y' AND QTDT.STATUS IN ('C','R'))) AS STOA_LIST_PRICE, MAX((SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE=A.BUYER AND TYPE='C001' AND CODE=A.BTOA_USER_DEPT)) AS BTOA_USER_DEPT, MAX(A.BTOA_REMARK) AS BTOA_REMARK, MAX(A.BUYER_ITEM_NO) AS BUYER_ITEM_NO, MAX(DECODE(A.ATOB_SEND_FLAG, 'N', DECODE(SIGN(TO_CHAR(SYSDATE,'YYYYMMDD') - A.BTOA_END_DATE),1,'지연','진행중'), DECODE(SIGN(A.ATOB_DATE - A.BTOA_END_DATE),1,'지연','정상'))) AS DELAY_STATUS, MAX(A.MAKER_NAME) AS MAKER_NAME, MAX((SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE='M001' AND CODE=A.ORIGIN_CODE)) AS ORIGIN_NAME, MAX(A.UNIT_MEASURE) AS UNIT_MEASURE, MAX(A.ITEM_QTY) AS ITEM_QTY, MAX((SELECT CM.COM_NAME_LOC FROM KEPQTDT QT, ICOMCMPY CM WHERE QT.BUYER=A.BUYER AND QT.QUOTATION_NO=A.QUOTATION_NO AND QT.QUOTATION_SEQ=A.QUOTATION_SEQ AND QT.REVISION=A.REVISION AND CM.COM_CODE=QT.AGENT AND QT.BID_SUCCESS_FLAG='Y' AND QT.STATUS IN ('C','R'))) AS AGENT_NAME, MAX(A.IMAGE_KEY) AS IMAGE_KEY, MAX((SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID=A.KEP_USER_ID AND STATUS IN ('C','R'))) AS KEP_USER_NAME, MAX(A.REG_ITEM_NO) AS REG_ITEM_NO, MAX((SELECT QTDT.AGENT FROM KEPQTDT QTDT WHERE QTDT.BUYER=A.BUYER AND QTDT.QUOTATION_NO=A.QUOTATION_NO AND QTDT.QUOTATION_SEQ=A.QUOTATION_SEQ AND QTDT.REVISION=A.REVISION AND QTDT.STATUS IN ('C','R') AND QTDT.BID_SUCCESS_FLAG='Y' )) AS AGENT, MAX(A.BTOA_USER_ID) AS BTOA_USER_ID, MAX(A.BTOA_END_TIME) AS BTOA_END_TIME, MAX(B.ATOS_END_TIME) AS ATOS_END_TIME, MAX(B.AGENT_REVISION) AS AGENT_REVISION, MAX(A.ATOB_DATE) AS ATOB_DATE, MAX(A.ATOB_TIME) AS ATOB_TIME, CASE WHEN MAX(B.ATOS_END_DATE)||MAX(B.ATOS_END_TIME) < TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS') THEN 'Y' ELSE 'N' END AS ATOS_END_FLAG, MAX((SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID=A.CMS_USER_ID)) AS CMS_USER_NAME, MAX(A.REF_NO) AS REF_NO, MAX(TRIM(A.REMARK_URL)) AS REMARK_URL FROM KEPRQDT A, KEPQTDT B WHERE A.BUYER IN ('KRDHIM0001','KRDHIM0003','KRDHIM0002','KRDAEW0023','KRDOOS0003','KRDAEW0043','KRDAEW0045') AND A.BUYER=B.BUYER(+) AND A.QUOTATION_NO=B.QUOTATION_NO(+) AND A.QUOTATION_SEQ=B.QUOTATION_SEQ(+) AND A.REVISION=B.REVISION(+) AND A.SO_CA_FLAG='SO' AND A.STATUS ^='D' AND A.QUOTATION_NO LIKE 'DI09%' AND A.RECV_FLAG ^='TS' AND A.STATUS IN ('C','R') AND B.STATUS(+) <> 'D' AND B.STATUS(+) <> 'O'
AND A.BTOA_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND B.ATOS_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.BTOA_END_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND B.ATOS_END_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.QUOTATION_NO = #{st_quotation_no}
AND A.BUYER = #{st_buyer_code}
AND A.KEP_USER_ID = #{st_kep_user_id}
AND A.BTOA_USER_NAME LIKE '%'||#{st_btoa_user_name}||'%'
AND (A.DESCRIPTION LIKE '%'||#{st_desc_spec}||'%' OR A.SPECIFICATION LIKE '%'||#{st_desc_spec}||'%')
AND A.BUYER_ITEM_NO LIKE '%'||#{st_buyer_item_no}||'%'
AND CASE WHEN A.RECV_FLAG='GD' THEN '견적취소' ELSE CASE WHEN A.RECV_FLAG = 'GS' THEN '결재진행중' ELSE CASE WHEN A.RECV_FLAG = 'GR' THEN '결재반려' ELSE CASE WHEN A.RECV_FLAG='PM' THEN '내부품의및카탈로그등록중' ELSE CASE WHEN A.RECV_FLAG='CC' THEN '합의완료+장바구니' ELSE CASE WHEN A.RECV_FLAG='CM' THEN '합의완료' ELSE CASE WHEN A.RECV_FLAG='NW' THEN 'CMS매핑의뢰' ELSE CASE WHEN A.RECV_FLAG='CR' THEN 'CMS매핑중' ELSE CASE WHEN A.RECV_FLAG='RJ' THEN 'CMS재요청' ELSE CASE WHEN A.KEP_USER_ID IS NULL THEN '구매사견적의뢰' ELSE CASE WHEN B.AGENT_REVISION=1 AND A.ATOB_UNIT_PRICE=0 AND ATOB_SEND_FLAG='N' AND B.BID_SUCCESS_FLAG<>'Y' THEN '공급사견적요청' ELSE CASE WHEN B.AGENT_REVISION<>1 AND A.ATOB_UNIT_PRICE=0 AND A.ATOB_SEND_FLAG='N' THEN '공급사재견적요청' ELSE CASE WHEN A.ATOB_UNIT_PRICE=0 AND A.ATOB_SEND_FLAG='N' AND B.BID_SUCCESS_FLAG='Y' THEN '공급사선정완료' ELSE CASE WHEN A.BTOA_NEGO_PRICE=0 AND A.ATOB_UNIT_PRICE<>0 AND A.ATOB_SEND_FLAG='Y' THEN '구매사견적제시' ELSE CASE WHEN A.BTOA_NEGO_PRICE<>0 AND A.ATOB_UNIT_PRICE=0 AND A.ATOB_SEND_FLAG='Y' THEN '구매사NEGO의뢰' ELSE CASE WHEN A.BTOA_NEGO_PRICE<>0 AND A.ATOB_UNIT_PRICE<>0 AND A.ATOB_SEND_FLAG='Y' THEN '구매사NEGO견적제출' END END END END END END END END END END END END END END END END LIKE '%'||#{st_sourcing_status}||'%'
GROUP BY A.BUYER, A.QUOTATION_NO, A.QUOTATION_SEQ, A.REVISION ) X ORDER BY X.DELAY_STATUS DESC, X.BUYER, X.QUOTATION_NO, X.QUOTATION_SEQ, X.BTOA_END_DATE, X.BTOA_END_TIME ) Y )Z
